/*
╔════════════════════════════════════════════════════════════════════╗
║  UTILITY CLASSES                                                   ║
╚════════════════════════════════════════════════════════════════════╝
*/

/* Screen-reader-only. Visually hidden but available to AT.
   Used for: skip links (visible on focus), alternate spoken pronunciations
   (e.g., the dual-span "arXiv" → "archive" pattern), "(opens in new tab)"
   notices, sr-only headings that label a region for landmark nav. */
.is-sr-only {
  position: absolute !important;
  width: 1px !important; height: 1px !important;
  padding: 0 !important; margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* External-link icon. Inline SVG (Lucide-style "external-link") used at
   the end of every link with target="_blank". Paired with sr-only text
   "(opens in new tab)". Both are required by the priority list. */
.external-icon {
  width: 11px; height: 11px;
  vertical-align: -1px;
  margin-left: 4px;
  opacity: 0.7;
  flex-shrink: 0;
}

/* Skip-link visible only on keyboard focus. The first focusable element
   on the page; lets keyboard/AT users bypass repetitive nav. */
.ds-skip-link {
  position: absolute;
  top: -100px; left: 8px;
  z-index: 200;
  background: var(--arxiv-ink);
  color: #fff;
  padding: 10px 16px;
  border-radius: 4px;
  text-decoration: none;
  font-weight: 600;
}
.ds-skip-link:focus-visible {
  top: 8px;
  outline: 3px solid var(--arxiv-focus-ring-dark);
  outline-offset: 2px;
}

/*
╔════════════════════════════════════════════════════════════════════╗
║  COMPONENT: Universal header (arXiv chrome)                        ║
╚════════════════════════════════════════════════════════════════════╝
  Intent
    The black bar at the top of every arXiv public page (post-Cornell
    spinout). NOT sticky — it scrolls away like any other content
    (decided 2026-06-11; sticky chrome is exceptional at arXiv and
    reader-only). Contains the logo and primary nav.

  Accessibility decisions (priorities.md: information architecture,
                           arxiv→archive pronunciation)
    - <header><nav aria-label="Main navigation"> is the landmark.
    - Logo aria-label and image alt say "archive" (the spoken pronunciation
      Ginsparg intended via Greek χ in "arXiv"). Dan Miner's research
      finding: screen readers without this hint say "ar-zhiv" / Roman
      numeral "XIV" — gibberish.
    - The search button opens a modal dialog (see search-overlay block);
      Cmd+K also opens it.
    - Decorative SVGs use aria-hidden + focusable="false" so SR doesn't
      announce them; the visible text labels are the accessible names.
    - Visible "About" link added so newcomers can self-orient (the
      "What is arXiv?" priority — research voice: Dan Miner "I have no
      clue what I am walking into").

  Tradeoff
    Header is Repository Brown (var(--arxiv-ink)) — same as the design system's
    background-dark token. Phase-2 spinout brand (post-June 2026). Black
    in phase 1 was visually identical so no transition work needed.
*/

/* Top announcement banner — light-blue dismissable strip above the
   black header. Matches the approved spinout-header-footer treatment.
   Stacked above the header (header stays sticky; banner scrolls away). */
.ds-announcement {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 6px 16px;
  background: var(--arxiv-active-bg);
  color: var(--arxiv-ink);
  font-family: var(--arxiv-font-sans);
  font-size: 0.8125rem;
  font-weight: 500;
  position: relative;
}
.ds-announcement-glyph {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}
.ds-announcement-text {
  font-weight: 600;
}
.ds-announcement-link {
  color: var(--arxiv-link-blue);
  text-decoration: underline;
  text-underline-offset: 2px;
  font-weight: 600;
}
.ds-announcement-link:hover { color: var(--arxiv-link-hover); }
.ds-announcement-close {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.125rem;
  line-height: 1;
  color: var(--arxiv-grey);
  padding: 4px 8px;
  border-radius: 3px;
}
.ds-announcement-close:hover { color: var(--arxiv-ink); background: rgba(0,0,0,0.05); }
.ds-announcement-close:focus-visible {
  outline: 2px solid var(--arxiv-link-blue);
  outline-offset: 1px;
}
@media (max-width: 520px) {
  .ds-announcement {
    flex-wrap: wrap;
    padding-right: 36px;  /* keep clear of the close button */
    text-align: center;
  }
}

.ds-site-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 24px;
  height: 52px;
  background: var(--arxiv-ink);
  /* NO sticky positioning — decided 2026-06-11 (Shamsi): the header
     scrolls away like any other content. Sticky chrome is exceptional
     at arXiv; only the HTML reader earns it (DESIGN-POLICIES.md). */
}
.ds-site-header-logo {
  display: flex;
  align-items: center;
  text-decoration: none;
  flex-shrink: 0;
  margin-right: auto;
}
.ds-site-header-logo img { height: 39px; width: auto; }
.ds-site-header-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}
.ds-site-header-nav a,
.ds-site-header-nav button {
  font-family: var(--arxiv-font-sans);
  font-size: 0.8125rem; /* 13px */
  font-weight: 500;
  color: var(--arxiv-grey-dis);
  text-decoration: none;
  padding: 6px 10px;
  border-radius: 4px;
  border: none;
  background: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.12s, color 0.12s;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.ds-site-header-nav a:visited { color: var(--arxiv-grey-dis); }
.ds-site-header-nav a:hover,
.ds-site-header-nav button:hover { background: #302c28; color: var(--arxiv-card-grey); }
.ds-site-header-nav a:focus-visible,
.ds-site-header-nav button:focus-visible {
  outline: 3px solid var(--arxiv-focus-ring-dark);
  outline-offset: 1px;
}
.ds-site-header-nav .ds-nav-icon { width: 16px; height: 16px; opacity: 0.65; flex-shrink: 0; }
.ds-site-header-divider {
  width: 1px; height: 20px;
  background: #4a433d;
  margin: 0 4px;
  flex-shrink: 0;
}
.ds-site-header-login {
  font-weight: 600 !important;
  color: var(--arxiv-card-grey) !important;
}

